mapper.update:
UPDATE handout_run_metrics
   SET result_status=#{status}, completed_at=#{completedAt}, failed_at=#{failedAt},
       acknowledged_at=#{acknowledgedAt}, ack_latency_ms=#{ackLatencyMs}, updated_at=#{updatedAt}
 WHERE run_id=#{runId}

UPDATE handout_run_metrics
   SET lease_wait_ms=#{elapsedMs}
 WHERE run_id=#{runId}

UPDATE handout_run_metrics
   SET dlq_count=COALESCE(dlq_count, 0) + 1, updated_at=UTC_TIMESTAMP(6)
 WHERE run_id=#{runId}

UPDATE handout_run_metrics
   SET publication_gate_at=#{publicationGateAt}, updated_at=#{publicationGateAt}
 WHERE run_id=#{runId}
